import random


def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    # Score tracking and opponent profiling.
    my_score = 0
    opp_score = 0
    opp_def = 0
    my_def = 0
    for a, b in history:
        if b == 'D':
            opp_def += 1
        if a == 'D':
            my_def += 1
        if a == 'C' and b == 'C':
            my_score += 3
            opp_score += 3
        elif a == 'C' and b == 'D':
            opp_score += 5
        elif a == 'D' and b == 'C':
            my_score += 5
        else:
            my_score += 1
            opp_score += 1

    opp_c = n - opp_def
    opp_rate = opp_def / float(n)

    # Consecutive trailing defections by opponent.
    opp_d_streak = 0
    for _, o in reversed(history):
        if o == 'D':
            opp_d_streak += 1
        else:
            break

    # Consecutive trailing defections by us.
    my_d_streak = 0
    for m, _ in reversed(history):
        if m == 'D':
            my_d_streak += 1
        else:
            break

    last_me, last_opp = history[-1]

    remaining = 100 - n

    # Hard endgame: defect on the last two rounds.
    if remaining <= 2:
        return 'D'

    # Sustained hostile opponent: defect to limit exploitation.
    if opp_d_streak >= 3:
        # Occasional forgiveness only if they have shown long-term cooperation.
        if opp_rate < 0.45 and rng.random() < 0.12:
            return 'C'
        return 'D'

    # Detect a pure cooperator and exploit it, but leave room to recover
    # if they start punishing.
    if opp_def == 0 and n >= 4:
        # Give them a cooperative base, then exploit heavily at the end.
        if remaining <= 6:
            return 'D'
        if opp_d_streak == 0 and my_d_streak == 0 and rng.random() < 0.25:
            return 'D'
        return 'C'

    # Mostly cooperative opponent: strong mutual cooperation with rare probes.
    if opp_rate < 0.15:
        if last_opp == 'D':
            # Immediate retaliation, but only once.
            if my_d_streak >= 1:
                return 'C'
            return 'D'
        if rng.random() < 0.04:
            return 'D'
        return 'C'

    # Moderate opponent: Tit-for-two-tats style with forgiveness.
    if opp_rate < 0.45:
        if opp_d_streak >= 2:
            return 'D'
        if last_opp == 'D':
            if rng.random() < 0.25:
                return 'C'
            return 'D'
        # If we have defected too much relative to them, show cooperation.
        if my_def > opp_def + 2 and last_opp == 'C':
            return 'C'
        if rng.random() < 0.06:
            return 'D'
        return 'C'

    # Hostile opponent: defect often, probe rarely.
    if opp_rate >= 0.75:
        if rng.random() < 0.05:
            return 'C'
        return 'D'

    # Middle/ambiguous opponent.
    if last_opp == 'C':
        if my_d_streak >= 2 and rng.random() < 0.6:
            return 'C'
        if rng.random() < 0.35:
            return 'D'
        return 'C'
    if opp_d_streak >= 2:
        return 'D'
    if rng.random() < 0.4:
        return 'C'
    return 'D'
